package ir.orix.school.enrollment.application;

import java.time.Clock; import java.time.LocalDate; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import ir.orix.school.audit.application.AuditService; import ir.orix.school.classroom.domain.*; import ir.orix.school.classroom.persistence.ClassSectionRepository; import ir.orix.school.enrollment.domain.*; import ir.orix.school.enrollment.persistence.*; import ir.orix.school.identity.domain.UserAccount; import ir.orix.school.identity.persistence.UserAccountRepository; import ir.orix.school.organization.domain.*; import ir.orix.school.organization.persistence.*; import ir.orix.school.people.domain.StudentProfile; import ir.orix.school.people.persistence.StudentProfileRepository; import ir.orix.school.shared.web.ApiException;

@Service
public class EnrollmentService {
 private static final Set<Enrollment.Status> CURRENT=Set.of(Enrollment.Status.ACTIVE,Enrollment.Status.WAITLISTED,Enrollment.Status.SUSPENDED);
 private final TenantRepository tenants; private final TenantMembershipRepository memberships; private final StudentProfileRepository students; private final ClassSectionRepository sections; private final EnrollmentRepository enrollments; private final EnrollmentStatusHistoryRepository history; private final UserAccountRepository accounts; private final AuditService audit; private final Clock clock;
 public EnrollmentService(TenantRepository tenants,TenantMembershipRepository memberships,StudentProfileRepository students,ClassSectionRepository sections,EnrollmentRepository enrollments,EnrollmentStatusHistoryRepository history,UserAccountRepository accounts,AuditService audit,Clock clock){this.tenants=tenants;this.memberships=memberships;this.students=students;this.sections=sections;this.enrollments=enrollments;this.history=history;this.accounts=accounts;this.audit=audit;this.clock=clock;}
 @Transactional(readOnly=true) public List<View> list(Long tenantId){return enrollments.findAllByTenantIdOrderByCreatedAtDesc(tenantId).stream().map(EnrollmentService::view).toList();}
 @Transactional(readOnly=true) public List<View> mine(Long tenantId,Long membershipId){return forStudent(tenantId,studentFromMembership(tenantId,membershipId).getId());}
 @Transactional(readOnly=true) public List<View> forStudent(Long tenantId,Long studentId){students.findByIdAndTenantId(studentId,tenantId).orElseThrow(notFound("STUDENT_NOT_FOUND")); return enrollments.findAllByTenantIdAndStudentIdOrderByCreatedAtDesc(tenantId,studentId).stream().map(EnrollmentService::view).toList();}
 @Transactional public View enroll(Long tenantId,Long actorId,Command c){ClassSection section=lockedSection(tenantId,c.classSectionId()); StudentProfile student=students.findByIdAndTenantId(c.studentId(),tenantId).orElseThrow(notFound("STUDENT_NOT_FOUND")); ensureNoCurrent(student.getId(),section.getId()); LocalDate start=c.startedOn()==null?LocalDate.now(clock):c.startedOn(); validateOpen(section,start); long occupied=enrollments.countActive(section.getId()); Enrollment.Status status=occupied<section.getCapacity()?Enrollment.Status.ACTIVE:c.allowWaitlist()?Enrollment.Status.WAITLISTED:null; if(status==null)throw conflict("CLASS_CAPACITY_REACHED","Class capacity has been reached."); Tenant tenant=tenant(tenantId);UserAccount actor=actor(actorId);Enrollment.Source source="self-service".equalsIgnoreCase(c.reason())?Enrollment.Source.SELF_SERVICE:Enrollment.Source.ADMIN;Enrollment enrollment=enrollments.save(new Enrollment(tenant,section,student,status,source,start,actor));history.save(new EnrollmentStatusHistory(tenant,enrollment,null,status,c.reason(),actor));audit.record(tenantId,actorId,"STUDENT_ENROLLED","ENROLLMENT",enrollment.getId(),Map.of("status",status.name()));return view(enrollment);}
 @Transactional public View cancel(Long tenantId,Long actorId,Long enrollmentId,String reason){Enrollment enrollment=enrollments.findByIdAndTenantId(enrollmentId,tenantId).orElseThrow(notFound("ENROLLMENT_NOT_FOUND")); if(!CURRENT.contains(enrollment.getStatus()))throw conflict("ENROLLMENT_NOT_CURRENT","Only a current enrollment can be cancelled."); LocalDate today=LocalDate.now(clock);Enrollment.Status previous=enrollment.changeStatus(Enrollment.Status.CANCELLED,today);UserAccount actor=actor(actorId);history.save(new EnrollmentStatusHistory(tenant(tenantId),enrollment,previous,Enrollment.Status.CANCELLED,reason,actor));audit.record(tenantId,actorId,"ENROLLMENT_CANCELLED","ENROLLMENT",enrollment.getId(),Map.of());return view(enrollment);}
 @Transactional public View transfer(Long tenantId,Long actorId,Long enrollmentId,TransferCommand c){Enrollment source=enrollments.findByIdAndTenantId(enrollmentId,tenantId).orElseThrow(notFound("ENROLLMENT_NOT_FOUND"));if(!CURRENT.contains(source.getStatus()))throw conflict("ENROLLMENT_NOT_CURRENT","Only a current enrollment can be transferred.");ClassSection target=lockedSection(tenantId,c.targetClassSectionId());if(target.getId().equals(source.getClassSection().getId()))throw conflict("SAME_TRANSFER_TARGET","Target class must be different.");ensureNoCurrent(source.getStudent().getId(),target.getId());LocalDate date=c.transferOn()==null?LocalDate.now(clock):c.transferOn();validateOpen(target,date);if(enrollments.countActive(target.getId())>=target.getCapacity())throw conflict("CLASS_CAPACITY_REACHED","Target class capacity has been reached.");Tenant tenant=tenant(tenantId);UserAccount actor=actor(actorId);Enrollment.Status previous=source.changeStatus(Enrollment.Status.TRANSFERRED,date);history.save(new EnrollmentStatusHistory(tenant,source,previous,Enrollment.Status.TRANSFERRED,c.reason(),actor));Enrollment destination=enrollments.save(new Enrollment(tenant,target,source.getStudent(),Enrollment.Status.ACTIVE,Enrollment.Source.TRANSFER,date,actor));history.save(new EnrollmentStatusHistory(tenant,destination,null,Enrollment.Status.ACTIVE,"Transferred from "+source.getId(),actor));audit.record(tenantId,actorId,"ENROLLMENT_TRANSFERRED","ENROLLMENT",source.getId(),Map.of("destinationEnrollmentId",destination.getId().toString()));return view(destination);}
 private void validateOpen(ClassSection section,LocalDate date){CourseOffering offering=section.getOffering();if(section.getStatus()!=ClassSection.Status.ACTIVE||offering.getStatus()!=CourseOffering.Status.OPEN)throw conflict("CLASS_NOT_OPEN","Class is not open for enrollment.");if(offering.getEnrollmentStartsOn()!=null&&date.isBefore(offering.getEnrollmentStartsOn())||offering.getEnrollmentEndsOn()!=null&&date.isAfter(offering.getEnrollmentEndsOn()))throw conflict("OUTSIDE_ENROLLMENT_WINDOW","Enrollment date is outside the allowed window.");}
 private void ensureNoCurrent(Long studentId,Long sectionId){if(enrollments.existsByStudentIdAndClassSectionIdAndStatusIn(studentId,sectionId,CURRENT))throw conflict("CURRENT_ENROLLMENT_EXISTS","Student already has a current enrollment in this class.");}
 private StudentProfile studentFromMembership(Long tenantId,Long membershipId){TenantMembership membership=memberships.findByIdAndTenantId(membershipId,tenantId).orElseThrow(notFound("MEMBERSHIP_NOT_FOUND")); return students.findByTenantIdAndPersonId(tenantId,membership.getPerson().getId()).orElseThrow(notFound("STUDENT_PROFILE_NOT_FOUND"));}
 private ClassSection lockedSection(Long tenantId,Long id){return sections.findLocked(id,tenantId).orElseThrow(notFound("CLASS_SECTION_NOT_FOUND"));} private Tenant tenant(Long id){return tenants.findById(id).orElseThrow(notFound("TENANT_NOT_FOUND"));} private UserAccount actor(Long id){return accounts.findById(id).orElseThrow(notFound("ACTOR_NOT_FOUND"));} private static ApiException conflict(String code,String detail){return new ApiException(HttpStatus.CONFLICT,code,detail);} private static java.util.function.Supplier<ApiException> notFound(String code){return ()->new ApiException(HttpStatus.NOT_FOUND,code,"The requested enrollment item was not found.");}
 private static View view(Enrollment e){ClassSection s=e.getClassSection();return new View(e.getId(),e.getStudent().getId(),e.getStudent().getStudentCode(),e.getStudent().getPerson().getFullName(),s.getId(),s.getName(),s.getOffering().getCourse().getTitle(),s.getOffering().getBranch().getName(),e.getStatus().name(),e.getSource().name(),e.getStartedOn(),e.getEndedOn());}
 public record Command(Long studentId,Long classSectionId,LocalDate startedOn,boolean allowWaitlist,String reason){} public record TransferCommand(Long targetClassSectionId,LocalDate transferOn,String reason){} public record View(Long id,Long studentId,String studentCode,String studentName,Long classSectionId,String className,String courseTitle,String branchName,String status,String source,LocalDate startedOn,LocalDate endedOn){}
}
